#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> countPeaks(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        int n = nums.size();
        std::vector<int> bit(n + 1, 0);

        auto add = [&](int idx, int val) {
            idx++;
            for (; idx <= n; idx += idx & (-idx)) bit[idx] += val;
        };

        auto query = [&](int idx) {
            idx++;
            int s = 0;
            for (; idx > 0; idx -= idx & (-idx)) s += bit[idx];
            return s;
        };

        auto isPeak = [&](int i) {
            if (i > 0 && i < n - 1 && nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) return 1;
            return 0;
        };

        std::vector<int> peak(n, 0);
        for (int i = 1; i < n - 1; ++i) {
            peak[i] = isPeak(i);
            if (peak[i]) add(i, 1);
        }

        std::vector<int> res;
        for (auto& q : queries) {
            if (q[0] == 1) {
                int l = q[1], r = q[2];
                if (r - l < 2) res.push_back(0);
                else res.push_back(query(r - 1) - query(l));
            } else {
                int idx = q[1], val = q[2];
                nums[idx] = val;
                for (int i = std::max(1, idx - 1); i <= std::min(n - 2, idx + 1); ++i) {
                    int newP = isPeak(i);
                    if (newP != peak[i]) {
                        add(i, newP - peak[i]);
                        peak[i] = newP;
                    }
                }
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] countPeaks(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] bit = new int[n + 1];

        int[] peak = new int[n];
        for (int i = 1; i < n - 1; i++) {
            if (nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) {
                peak[i] = 1;
                add(bit, n, i, 1);
            }
        }

        List<Integer> ans = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int l = q[1], r = q[2];
                if (r - l < 2) ans.add(0);
                else ans.add(query(bit, r - 1) - query(bit, l));
            } else {
                int idx = q[1], val = q[2];
                nums[idx] = val;
                for (int i = Math.max(1, idx - 1); i <= Math.min(n - 2, idx + 1); i++) {
                    int newP = (nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) ? 1 : 0;
                    if (newP != peak[i]) {
                        add(bit, n, i, newP - peak[i]);
                        peak[i] = newP;
                    }
                }
            }
        }
        int[] res = new int[ans.size()];
        for (int i = 0; i < ans.size(); i++) res[i] = ans.get(i);
        return res;
    }

    private void add(int[] bit, int n, int idx, int val) {
        idx++;
        for (; idx <= n; idx += idx & (-idx)) bit[idx] += val;
    }

    private int query(int[] bit, int idx) {
        idx++;
        int s = 0;
        for (; idx > 0; idx -= idx & (-idx)) s += bit[idx];
        return s;
    }
}

